class Solution {
public:
    long long nCr(int n, int r) {
        if (r > n - r) r = n - r;
        long long res = 1;
        for (int i = 0; i < r; ++i) {
            res = res * (n - i) / (i + 1);
        }
        return res;
    }
    vector<vector<int>> generate(int numRows) {
        vector<vector<int>> ans;
        for (int i = 0; i < numRows; ++i) {
            vector<int> row;
            for (int j = 0; j <= i; ++j) {
                row.push_back((int)nCr(i, j));
            }
            ans.push_back(row);
        }
        return ans;
    }
};

