from typing import List
class Solution:
    def generate(self, numRows: int) -> List[List[int]]:
        def nCr(n: int, r: int) -> int:
            if r > n - r:
                r = n - r
            res = 1
            for i in range(r):
                res = res * (n - i) // (i + 1)
            return res
        ans = []
        for i in range(numRows):
            row = [nCr(i, j) for j in range(i + 1)]
            ans.append(row)
        return ans

